const NOT_IMPLEMENTED = /not (registered|found|implemented|supported|installed|allowed by acl)|command not found|no such|unknown command|unavailable|plugin .*not/i;

let _seq = 0;
const uniq = (p: string) => `${p}_${Date.now().toString(36)}_${++_seq}`;
const delay = (ms: number) => new Promise((r) => setTimeout(r, ms));

async function blind(fn: () => Promise<unknown>): Promise<void> {
  try {
    await fn();
  } catch (e) {
    const m = String((e as Error)?.message ?? e);
    // Explicit skip intent must never be swallowed by the blind coverage
    // wrapper: relay it so runTests sees the `skip:` prefix (status 'skip')
    // instead of recording a false pass below.
    if (m.startsWith('skip:')) throw e;
    if (NOT_IMPLEMENTED.test(m)) throw new Error('skip: ' + m);
    // 其他错误也是覆盖（错误分支被点亮）——按通过计
  }
}

function driverCase(name: string, fn: () => Promise<unknown>): TestCase {
  return { name: 'driver: ' + name, category: 'driver', timeout: 3000, fn: () => blind(fn) };
}

function sideCase(name: string, fn: () => Promise<unknown>): TestCase {
  return { name: 'side-replay: ' + name, category: 'side-effect', timeout: 5000, fn: () => blind(fn) };
}

function badCase(name: string, fn: () => Promise<unknown>): TestCase {
  return { name: 'bad-input: ' + name, category: 'driver', timeout: 5000, fn: () => blind(fn) };
}

