// --- Unattended-build gate for modal-waiting side replays --------------------
//
// requestPermissions() blocks on the system permission dialog and message()
// blocks on a modal message dialog: both settle only after USER interaction
// and hang forever in an unattended run (blind() guards rejections, not a
// promise that never settles, so the runner's withTimeout burns its budget).
// Device evidence 2026-10-28: on the coverage build (VITE_COVERAGE_TESTS=true)
// these two cases failed deterministically 2/2 across two rounds (report
// lines 548 and 553) while the other 13 side replays that ran settled
// unattended (581 ok, only these two red). Suite hygiene, not a platform
// defect. Unattended means either suite flag is set -- VITE_AUTOTEST (std
// autotest build) or VITE_COVERAGE_TESTS (coverage build) -- the same
// predicate as TestRunner.svelte isAutotest/coverageTests. On those builds
// the cases skip instead of reporting a platform-inherent failure
// (precedent 6232bcd24 P3-3 iframe gate). Assembly reality (TestRunner.svelte):
// sideReplayTests is only spliced into the suite when VITE_COVERAGE_TESTS is
// set, so the coverage build is the ONLY path that reaches these two cases -
// and there the gate below ALWAYS fires (the predicate keys on
// VITE_COVERAGE_TESTS itself), so the case bodies are unreachable in every
// assembled suite. That is exactly why these two cases now carry no other
// gate: 524a60ad8's skipOnMobile pair on them was a DEAD gate (in their only
// assembly the unattended gate always skips them, so whichever gate fired
// first the outcome was the same skip - the earlier mobile gate could never
// change an outcome, at most the reason string) and was removed accordingly;
// float.hide's own skipOnMobile stays - that case is assembled ONLY in the
// coverage build too (the same TestRunner.svelte splice puts driverTests and
// sideReplayTests into one coverageTests batch behind VITE_COVERAGE_TESTS;
// std builds inject neither), but the coverage build itself also runs on OHOS
// mobile FORMS, and there the case's create step (create_borderless_window)
// is cfg(desktop)-only in cmd.rs and fails deterministically - skipOnMobile
// converts that guaranteed failure into a runner-grade skip, so the gate IS
// live in the only assembly that reaches the case (unlike the deleted pair
// above: in the modal side cases' only assembly the unattended gate always
// skips them, so whichever gate fired first the outcome was the same skip -
// the mobile gate there was outcome-equivalent, never outcome-relevant). The
// VITE_AUTOTEST arm is defensive - it mirrors the isAutotest idiom in case a
// future assembly change ever adds these replays to the std autotest suite.
// In an interactive demo build (neither flag set) the side-replay batch is
// not assembled at all, so the two modals never run there; their interactive
// surface is covered by the manual dialog/notification entries in
// doc/manual_tests.md.
function skipModalWaitOnUnattendedBuild(what: string): void {
  const unattended =
    ['true', '1'].includes(String(import.meta.env.VITE_AUTOTEST)) ||
    ['true', '1'].includes(String(import.meta.env.VITE_COVERAGE_TESTS));
  if (unattended) {
    skip(`waits for user interaction (${what}) which never settles in an unattended run`);
  }
}

